// Small deterministic teaching models, not live network probes or protocol stacks.
export const escapeHTML=v=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
export function packet(payload,hop){return {payload,tcp:payload+20,ip:payload+40,frame:payload+58,ttl:64-hop,source:'192.0.2.10',destination:'198.51.100.20',link:hop===0?'Laptop → gateway':hop===1?'Gateway → transit':'Transit → server LAN'};}
export const routes=[{prefix:'0.0.0.0/0',next:'Default uplink'},{prefix:'10.0.0.0/8',next:'Private backbone'},{prefix:'10.42.0.0/16',next:'Regional router'},{prefix:'10.42.7.0/24',next:'Local subnet'}];
const ipNumber=ip=>ip.split('.').reduce((n,x)=>n*256+Number(x),0);
export function routeFor(ip,specific=true){return routes.filter(r=>specific||!r.prefix.endsWith('/24')).filter(r=>{const [network,bits]=r.prefix.split('/'),size=2**(32-Number(bits));return Math.floor(ipNumber(ip)/size)===Math.floor(ipNumber(network)/size);}).sort((a,b)=>Number(b.prefix.split('/')[1])-Number(a.prefix.split('/')[1]))[0];}
export function dnsLookup(s){const hit=s.cache&&s.now<s.cache.expires;return {...s,cache:hit?s.cache:{address:s.authority,expires:s.now+Number(s.ttl)},answer:hit?s.cache.address:s.authority,hit,lookups:s.lookups+1};}
export function mtuModel(payload,lastMtu,tunnel,packetize){const links=[1500,tunnel?1420:1500,lastMtu],mtu=Math.min(...links),maxPayload=mtu-48,chunks=packetize?Math.ceil(payload/maxPayload):1;return {links,mtu,maxPayload,chunks,size:Math.min(payload,packetize?maxPayload:payload)+48,delivered:packetize||payload+48<=mtu};}
export function delivery(arrived,protocol){const unique=[...new Set(arrived)];let prefix=0;while(unique.includes(prefix+1))prefix++;return {visible:protocol==='TCP'?Array.from({length:prefix},(_,i)=>i+1):unique,prefix,ack:1+prefix*100,buffered:protocol==='TCP'?unique.filter(x=>x>prefix):[]};}
export function sendBudget(cwnd,rwnd,inflight){return Math.max(0,Math.min(cwnd,rwnd)-inflight);}
export function congestionStep(s,loss=false){const threshold=loss?Math.max(2,Math.floor(s.cwnd/2)):s.threshold,cwnd=loss?Math.max(1,Math.floor(s.cwnd/2)):s.cwnd<s.threshold?Math.min(s.cwnd*2,s.threshold):s.cwnd+1;return {...s,cwnd,threshold,history:[...s.history,cwnd].slice(-16),round:s.round+1};}
export function connectionLoad(count,reuse,hold){return {opens:reuse?1:count,handshakeMs:(reuse?1:count)*hold};}
export function handshake(protocol,reused,rtt){const setup=reused?0:protocol==='HTTP/3'?1:2;return {setup,firstByte:(setup+1)*rtt,rows:reused?[['Request → first byte',0,rtt]]:protocol==='HTTP/3'?[['QUIC + TLS',0,rtt],['Request → first byte',rtt,rtt]]:[['TCP establishment',0,rtt],['TLS 1.3',rtt,rtt],['Request → first byte',2*rtt,rtt]]};}
export function multiplex(protocol,lost,repaired){const packets=[{stream:'A',part:1},{stream:'B',part:1},{stream:'A',part:2},{stream:'B',part:2},{stream:'A',part:3},{stream:'B',part:3}];const got=packets.map((p,i)=>({...p,arrived:repaired||i!==lost-1}));const prefix=got.findIndex(p=>!p.arrived);return got.map((p,i)=>({...p,ready:p.arrived&&(protocol==='HTTP/2'?prefix===-1||i<prefix:!got.slice(0,i).some(x=>x.stream===p.stream&&!x.arrived))}));}
export function methodEffect(method,repeats){return {value:repeats===0?0:method==='PUT'?7:method==='POST'?repeats:0,safe:method==='GET',idempotent:method!=='POST'};}
export function conditional(mode,matches){return mode==='Read'?{status:matches?304:200,body:matches?0:120}:{status:matches?200:412,body:0};}
export function proxyIdentity(clientClaim,trustProxy){return trustProxy?'198.51.100.27':clientClaim?'203.0.113.99':'192.0.2.5';}
export function balance(jobs,policy,excludeSlow){const finish=[0,0,0],counts=[0,0,0],assignments=[];const eligible=excludeSlow?[0,1]:[0,1,2];for(let n=0;n<jobs;n++){const target=policy==='Round robin'?eligible[n%eligible.length]:eligible.reduce((best,i)=>finish[i]<finish[best]?i:best,eligible[0]);const duration=target===2?4:1;assignments.push({target,start:finish[target],duration});finish[target]+=duration;counts[target]++;}return {finish,counts,assignments,total:Math.max(...finish)};}
export function cacheDecision({age,maxAge,policy,changed,shared}){const stored=policy!=='no-store'&&!(policy==='private'&&shared),fresh=stored&&policy!=='no-cache'&&age<maxAge;return {stored,fresh,action:!stored?'Fetch full response':fresh?'Reuse cached response':changed?'Revalidate → 200 + body':'Revalidate → 304',bytes:fresh?0:stored&&!changed?0:120,network:!fresh};}
export function variant(encoding,vary,privateResponse,shared){const usable=!(privateResponse&&shared),key=vary?`/report | ${encoding}`:'/report';return {key,usable,served:usable?(vary?encoding:'br'):'Origin response',mismatch:usable&&!vary&&encoding==='identity'};}
export function originResult(target,preflight,allow){const same=new URL(target).origin==='https://app.example';const mixed=new URL(target).protocol==='http:';return {same,sent:!mixed&&(same||!preflight||allow),readable:!mixed&&(same||allow)};}
export function renderPath(css,js,defer){const html=40,cssEnd=20+css,jsEnd=20+js;const executeStart=Math.max(jsEnd,cssEnd,defer?html:0),executeEnd=executeStart+30;const domReady=defer?html:executeEnd+20,opportunity=Math.max(domReady,cssEnd),paint=opportunity<executeStart?opportunity:Math.max(opportunity,executeEnd);return {html,cssEnd,jsEnd,executeStart,executeEnd,domReady,paint,ready:Math.max(domReady,executeEnd),rows:[['HTML parsing',0,20],['CSS fetch',20,css],['JS fetch',20,js],['JS execute',executeStart,30],['Remaining HTML',defer?20:executeEnd,20]]};}
export function mainThread(chunks){const work=120,gap=5,part=work/chunks;const rows=Array.from({length:chunks},(_,i)=>['Work '+(i+1),i*(part+gap),part]);const arrival=25;let input=arrival;for(const [,start,duration]of rows){if(arrival>=start&&arrival<start+duration){input=start+duration;break;}}return {rows,input,delay:input-arrival,total:work+(chunks-1)*gap};}
export function workerCache(strategy,online,version,cached='v1'){if(strategy==='Cache first'&&cached)return {shown:cached,network:false,updated:cached};return online?{shown:version,network:true,updated:version}:{shown:cached,network:true,updated:cached};}
export function redirectResult(status,method,hops,rtt){return {method:status==='303'&&method!=='HEAD'?'GET':method,extra:hops*rtt,bodyRetained:status!=='303'&&method==='POST'};}
export function compression(kb,ratio,mbps,cpu){const raw=kb*8/mbps,compressed=kb*ratio/100*8/mbps;return {raw,compressed,cpu,total:compressed+cpu,saved:raw-compressed-cpu};}
export const eventTimes=[1,4,9,13,19];
export function realtime(mode,interval){const poll=mode==='Polling',deliveries=eventTimes.map(t=>poll?Math.ceil(t/interval)*interval:t),requests=poll?Math.floor(20/interval):1;return {deliveries,requests,average:deliveries.reduce((n,t,i)=>n+t-eventTimes[i],0)/eventTimes.length,bidirectional:mode==='WebSocket'};}
export function queueStep(s){const consumed=Math.min(s.queue,s.consume),room=Math.max(0,s.capacity-(s.queue-consumed)),accepted=s.backpressure?Math.min(s.produce,room):s.produce,queue=s.queue-consumed+accepted;return {...s,queue,produced:s.produced+accepted,consumed:s.consumed+consumed,paused:s.produce-accepted,tick:s.tick+1};}
export function waterfall({rtt,dns,reuse,server,body}){const stages=[['DNS',dns],['TCP',reuse?0:rtt],['TLS',reuse?0:rtt],['Request + server',rtt+server],['Response body',body]];let t=0;const rows=stages.map(([l,d])=>{const row=[l,t,d];t+=d;return row;});return {rows,total:t,ttfb:t-body};}
export function transfer(mbps,rtt,windowKB,sizeMB){const windowMbps=windowKB*1000*8/rtt/1000,rate=Math.min(mbps,windowMbps);return {windowMbps,rate,seconds:sizeMB*8/rate,bdpKB:mbps*rtt/8};}
export function deadline(connect,firstByte,chunks,gap,idle,total){const arrivals=Array.from({length:chunks},(_,i)=>connect+firstByte+i*gap);const completion=arrivals.at(-1);const idleAt=firstByte>=idle?connect+idle:chunks>1&&gap>=idle?arrivals[0]+idle:null;const timeoutAt=Math.min(total,idleAt??Infinity);return {arrivals,completion,timeout:timeoutAt<=completion,at:Math.min(timeoutAt,completion),reason:timeoutAt<=completion?(total<= (idleAt??Infinity)?'Total deadline':'Read idle timeout'):'Completed'};}
